const VERSION: &str = "caesiumclt 1.3.0";
const ABOUT: &str = "A fast and efficient lossy and/or lossless image compression tool";

fn usage_line(extra_opts: &str) -> String {
    let pre = if extra_opts.is_empty() {
        "[OPTIONS]".to_string()
    } else {
        extra_opts.to_string()
    };
    format!(
        "Usage: executable {} <--quality <QUALITY>|--lossless|--max-size <MAX_SIZE>> <--output <OUTPUT>|--same-folder-as-input> {}",
        pre, "[FILES]..."
    )
}

fn usage_line_files_req(extra_opts: &str) -> String {
    let pre = if extra_opts.is_empty() {
        "".to_string()
    } else {
        format!("{} ", extra_opts)
    };
    format!(
        "Usage: executable {}<--quality <QUALITY>|--lossless|--max-size <MAX_SIZE>> <--output <OUTPUT>|--same-folder-as-input> <FILES>...",
        pre
    )
}

fn print_short_help() {
    println!("{}", ABOUT);
    println!();
    println!("{}", usage_line(""));
    println!();
    println!("Arguments:");
    println!("  [FILES]...  Input files or directories to process");
    println!();
    println!("Options:");
    let opts = short_options();
    for (left, right) in opts {
        let wrapped = wrap_text(&right, 80 - 10 - left.len());
