        ("    --jpeg-chroma-subsampling <JPEG_CHROMA_SUBSAMPLING>".to_string(), "Chroma subsampling for JPEG files [default: auto] [possible values: 4:4:4, 4:2:2, 4:2:0, 4:1:1, auto]".to_string()),
        ("    --jpeg-baseline".to_string(), "Output baseline JPEG instead of progressive (default)".to_string()),
        ("    --zopfli".to_string(), "Use zopfli for PNG optimization (significantly slower but better compression)".to_string()),
        ("-e, --exif".to_string(), "Keep EXIF metadata during compression".to_string()),
