fn opt_header(opt: &OptSpec) -> String {
    let prefix = match opt.short {
        Some(c) => format!("-{}, --{}", c, opt.long),
        None => format!("    --{}", opt.long),
    };
    match opt.val_name {
        Some(v) => format!("{} <{}>", prefix, v),
        None => prefix,
    }
}

fn print_usage_short() -> String {
    format!("Usage: executable [OPTIONS] <--quality <QUALITY>|--lossless|--max-size <MAX_SIZE>> <--output <OUTPUT>|--same-folder-as-input> [FILES]...")
}

fn print_short_help() {
    println!("{}", ABOUT);
    println!();
    println!("{}", print_usage_short());
    println!();
    println!("Arguments:");
    println!("  [FILES]...  Input files or directories to process");
    println!();
    println!("Options:");
    for opt in options_spec() {
        let header = opt_header(&opt);
        // Opt header with leading "  "
        let line = format!("  {}", header);
        println!("{}", line);
        // Description line - 10 space indent, with inline defaults/possible
        let mut desc = opt.description_short.to_string();
        if let Some(dv) = opt.default_value {
            desc.push_str(&format!(" [default: {}]", dv));
        }
        if let Some(pv) = &opt.possible_values {
            desc.push_str(&format!(" [possible values: {}]", pv.join(", ")));
        }
        println!("          {}", desc);
    }
    println!("  -h, --help");
    println!("          Print help (see more with '--help')");
    println!("  -V, --version");
    println!("          Print version");
}

fn print_long_help() {
    println!("{}", ABOUT);
    println!();
    println!("{}", print_usage_short());
    println!();
    println!("Arguments:");
