// ============================================================================
// Argument parsing
// ============================================================================

#[derive(Default, Debug, Clone)]
struct Args {
    quality: Option<u32>,
    lossless: bool,
    max_size: Option<u64>,
    width: Option<u32>,
    height: Option<u32>,
    long_edge: Option<u32>,
    short_edge: Option<u32>,
    no_upscale: bool,
    output: Option<String>,
    same_folder_as_input: bool,
    format: String,
    png_opt_level: u32,
    jpeg_chroma_subsampling: String,
    jpeg_baseline: bool,
    zopfli: bool,
    exif: bool,
    keep_dates: bool,
    strip_icc: bool,
    suffix: Option<String>,
    recursive: bool,
    keep_structure: bool,
    dry_run: bool,
    threads: u32,
    overwrite: String,
    min_savings: Option<MinSavings>,
    quiet: bool,
    verbose: u32,
    // Positional
    files: Vec<String>,
}

#[derive(Debug, Clone)]
enum MinSavings {
    Percent(f64),   // e.g., 10.0 = 10%
    Bytes(u64),
}

struct ClapError {
    msg: String,
    usage_hint: String, // parts between "Usage: executable " and " <--quality..."
}

impl ClapError {
    fn new(msg: String) -> Self {
        ClapError { msg, usage_hint: String::new() }
    }
    fn with_hint(msg: String, hint: String) -> Self {
        ClapError { msg, usage_hint: hint }
    }
}

fn emit_clap_error(e: &ClapError, req_files: bool) -> ExitCode {
    let _ = writeln!(std::io::stderr(), "error: {}", e.msg);
    let _ = writeln!(std::io::stderr());
    if !req_files {
        let _ = writeln!(std::io::stderr(), "{}", usage_line_default());
    } else {
        let files_part = if req_files { "<FILES>..." } else { "[FILES]..." };
        let prefix = if e.usage_hint.is_empty() {
            String::new()
        } else {
            format!("{} ", e.usage_hint)
        };
        let _ = writeln!(std::io::stderr(),
            "Usage: executable {}<--quality <QUALITY>|--lossless|--max-size <MAX_SIZE>> <--output <OUTPUT>|--same-folder-as-input> {}",
            prefix, files_part);
    }
    let _ = writeln!(std::io::stderr());
    let _ = writeln!(std::io::stderr(), "For more information, try '--help'.");
    ExitCode::from(2)
}

// Parse using a "long-first" priority: --long=value, --long value, -X value, -X=value, combined short flags
// Returns Err(ClapError) on bad parse

fn is_num_char(c: char) -> bool {
    c == '-' || c.is_ascii_digit()
}

fn looks_like_negative_value(s: &str) -> bool {
    if !s.starts_with('-') { return false; }
    if s.len() < 2 { return false; }
    let rest = &s[1..];
    // "-1" -> negative number. But "-q", "-R" etc. are options.
    rest.chars().next().map_or(false, |c| c.is_ascii_digit())
}

// Find a short option description match for "unknown --flag" tip generation.
// Simple string similarity (case sensitive length difference).
fn best_long_match(flag: &str) -> Option<&'static str> {
    let known = [
        "quality","lossless","max-size","width","height","long-edge","short-edge","no-upscale",
        "output","same-folder-as-input","format","png-opt-level","jpeg-chroma-subsampling",
        "jpeg-baseline","zopfli","exif","keep-dates","strip-icc","suffix","recursive",
        "keep-structure","dry-run","threads","overwrite","min-savings","quiet","verbose","help","version",
    ];
    // strip leading dashes from flag
    let name = flag.trim_start_matches('-');
    if name.is_empty() { return None; }
    // Look for starts-with or Levenshtein-like small distance
    let mut best: Option<(usize, &'static str)> = None;
    for k in known {
        let d = osa_distance(name, k);
        if d <= 3 {
            match &best {
                None => best = Some((d, k)),
                Some((bd, _)) if d < *bd => best = Some((d, k)),
                _ => {}
            }
        }
    }
    best.map(|(_, k)| k)
}

// Simple edit distance (Damerau-Levenshtein-ish) to mirror clap's "did you mean"
fn osa_distance(a: &str, b: &str) -> usize {
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();
    let (n, m) = (a.len(), b.len());
    if n == 0 { return m; }
    if m == 0 { return n; }
    let mut d = vec![vec![0usize; m+1]; n+1];
    for i in 0..=n { d[i][0] = i; }
    for j in 0..=m { d[0][j] = j; }
    for i in 1..=n {
        for j in 1..=m {
            let cost = if a[i-1] == b[j-1] { 0 } else { 1 };
            d[i][j] = [
                d[i-1][j] + 1,
                d[i][j-1] + 1,
                d[i-1][j-1] + cost,
            ].iter().copied().min().unwrap();
            if i > 1 && j > 1 && a[i-1] == b[j-2] && a[i-2] == b[j-1] {
                d[i][j] = d[i][j].min(d[i-2][j-2] + 1);
            }
        }
    }
    d[n][m]
}
