fn parse_args(argv: &[String]) -> Result<Args, ClapError> {
    // Default values
    let mut a = Args::default();
    a.format = "original".to_string();
    a.png_opt_level = 3;
    a.jpeg_chroma_subsampling = "auto".to_string();
    a.overwrite = "all".to_string();
    a.verbose = 1;
    a.threads = 0;

    // Track which options were seen for conflict detection
    // Order of seeing matters for error messages
    let mut seen_order: Vec<&'static str> = Vec::new();
    let mut mark = |name: &'static str, order: &mut Vec<&'static str>| {
        if !order.contains(&name) { order.push(name); }
    };

    let mut idx = 1;
    let mut positional_only = false;

    let mut quiet_source: Option<String> = None; // whether -Q or --quiet
    let mut verbose_source: Option<String> = None;

    while idx < argv.len() {
        let arg = &argv[idx];
        if positional_only {
            a.files.push(arg.clone());
            idx += 1;
            continue;
        }
        if arg == "--" {
            positional_only = true;
            idx += 1;
            continue;
        }
        if arg == "--help" {
            print_long_help();
            std::process::exit(0);
        }
        if arg == "-h" {
            print_short_help();
            std::process::exit(0);
        }
        if arg == "--version" || arg == "-V" {
            println!("{}", VERSION_STR);
            std::process::exit(0);
        }

        // Long option forms
        if arg.starts_with("--") {
            let (name, eq_val): (&str, Option<&str>) = match arg.find('=') {
