                    a.long_edge = Some(n);
                    mark("long-edge", &mut seen_order);
                }
                "short-edge" => {
                    let v = take_value(&mut idx, argv, eq_val, pretty)?;
                    let n = parse_u32_std(&v, pretty)?;
                    check_resize_conflict("short-edge", &seen_order)?;
                    a.short_edge = Some(n);
                    mark("short-edge", &mut seen_order);
                }
                "no-upscale" => { a.no_upscale = true; }
