                    check_possible_values(&v, pretty, &["jpeg","png","gif","webp","tiff","original"])?;
                    a.format = v;
                }
                "png-opt-level" => {
                    let v = take_value(&mut idx, argv, eq_val, pretty)?;
                    let n: u32 = match v.parse::<u32>() {
