                "exif" => { a.exif = true; }
                "keep-dates" => { a.keep_dates = true; }
                "strip-icc" => { a.strip_icc = true; }
                "suffix" => {
                    let v = take_value(&mut idx, argv, eq_val, pretty)?;
                    a.suffix = Some(v);
                }
