                        "invalid value '{}' for '{}': Invalid size format: '{}'. Use percentage (e.g., '10%'), size with unit (e.g., '100KB', '1MB'), or plain number as bytes",
                        v, pretty, v)))?;
                    a.min_savings = Some(ms);
                }
                "quiet" => {
                    if verbose_source.is_some() {
                        return Err(ClapError::with_hint(
                            "the argument '--verbose <VERBOSE>' cannot be used with '--quiet'".to_string(),
