        "output" => "--output <OUTPUT>".to_string(),
        "same-folder-as-input" => "--same-folder-as-input".to_string(),
        "quiet" => "--quiet".to_string(),
        "verbose" => "--verbose <VERBOSE>".to_string(),
        _ => format!("--{}", name),
    }
}
