fn take_value(idx: &mut usize, argv: &[String], eq_val: Option<&str>, pretty: &str) -> Result<String, ClapError> {
    if let Some(v) = eq_val { return Ok(v.to_string()); }
    if *idx + 1 >= argv.len() {
        return Err(ClapError::new(format!("a value is required for '{}' but none was supplied", pretty)));
    }
    *idx += 1;
    Ok(argv[*idx].clone())
}

fn parse_u32_std(v: &str, pretty: &str) -> Result<u32, ClapError> {
    match v.parse::<u32>() {
        Ok(x) => Ok(x),
        Err(e) => {
            let kind = format!("{}", e);
            let detail = if kind.contains("empty") {
                "cannot parse integer from empty string".to_string()
            } else if kind.contains("too large") || kind.contains("too small") || kind.contains("overflow") {
                "number too large to fit in target type".to_string()
            } else {
                "invalid digit found in string".to_string()
            };
            Err(ClapError::new(format!(
                "invalid value '{}' for '{}': {}",
                v, pretty, detail)))
        }
    }
}

fn check_possible_values(val: &str, pretty: &str, allowed: &[&str]) -> Result<(), ClapError> {
    if allowed.contains(&val) { return Ok(()); }
    let msg = format!(
        "invalid value '{}' for '{}'\n  [possible values: {}]",
        val, pretty, allowed.join(", "));
    Err(ClapError::with_hint(msg, "".to_string()))
}

fn check_compression_conflict(new: &str, order: &[&'static str]) -> Result<(), ClapError> {
    for &s in order {
        if s == "quality" || s == "lossless" || s == "max-size" {
            if s == new { continue; }
            let a = pretty_of(s);
            let b = pretty_of(new);
            return Err(ClapError::with_hint(
                format!("the argument '{}' cannot be used with '{}'", a, b),
                "".to_string(),
            ));
        }
    }
    Ok(())
}

fn check_output_conflict(new: &str, order: &[&'static str]) -> Result<(), ClapError> {
    for &s in order {
        if s == "output" || s == "same-folder-as-input" {
            if s == new { continue; }
            let a = pretty_of(s);
            let b = pretty_of(new);
            return Err(ClapError::with_hint(
                format!("the argument '{}' cannot be used with '{}'", a, b),
                "".to_string(),
            ));
        }
    }
    Ok(())
}

fn check_resize_conflict(new: &str, order: &[&'static str]) -> Result<(), ClapError> {
    // width/height are group 1 (both can coexist); long-edge and short-edge each alone
    // Rule: width or height cannot be used with long-edge/short-edge. long-edge cannot be used with short-edge.
    let is_wh = |s: &str| s == "width" || s == "height";
    let is_le = |s: &str| s == "long-edge";
    let is_se = |s: &str| s == "short-edge";
    for &s in order {
        let a = pretty_of(s);
        let b = pretty_of(new);
        if is_wh(s) && (is_le(new) || is_se(new)) { return Err(conflict(a,b)); }
        if is_le(s) && (is_wh(new) || is_se(new)) { return Err(conflict(a,b)); }
        if is_se(s) && (is_wh(new) || is_le(new)) { return Err(conflict(a,b)); }
    }
    Ok(())
}

fn conflict(a: String, b: String) -> ClapError {
    ClapError::with_hint(
        format!("the argument '{}' cannot be used with '{}'", a, b),
        a.clone(),
    )
}

fn pretty_of(name: &str) -> String {
    match name {
        "quality" => "--quality <QUALITY>".to_string(),
        "lossless" => "--lossless".to_string(),
        "max-size" => "--max-size <MAX_SIZE>".to_string(),
        "width" => "--width <WIDTH>".to_string(),
        "height" => "--height <HEIGHT>".to_string(),
        "long-edge" => "--long-edge <LONG_EDGE>".to_string(),
        "short-edge" => "--short-edge <SHORT_EDGE>".to_string(),
        "output" => "--output <OUTPUT>".to_string(),
        "same-folder-as-input" => "--same-folder-as-input".to_string(),
        "quiet" => "--quiet".to_string(),
        "verbose" => "--verbose <VERBOSE>".to_string(),
        _ => format!("--{}", name),
    }
}
