#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Seen {
    NotSeen,
    FromShort,
    FromLong,
}

fn parse_args(argv: &[String]) -> Result<Args, ClapError> {
    // Default values
    let mut a = Args::default();
    a.format = "original".to_string();
    a.png_opt_level = 3;
    a.jpeg_chroma_subsampling = "auto".to_string();
    a.overwrite = "all".to_string();
    a.verbose = 1;
    a.threads = 0;

    // Track which options were seen for conflict detection
    // Order of seeing matters for error messages
    let mut seen_order: Vec<&'static str> = Vec::new();
    let mut mark = |name: &'static str, order: &mut Vec<&'static str>| {
        if !order.contains(&name) { order.push(name); }
    };

    let mut idx = 1;
    let mut positional_only = false;

    let mut quiet_source: Option<String> = None; // whether -Q or --quiet
    let mut verbose_source: Option<String> = None;

    while idx < argv.len() {
        let arg = &argv[idx];
        if positional_only {
            a.files.push(arg.clone());
            idx += 1;
            continue;
        }
        if arg == "--" {
            positional_only = true;
            idx += 1;
            continue;
        }
        if arg == "--help" {
            print_long_help();
            std::process::exit(0);
        }
        if arg == "-h" {
            print_short_help();
            std::process::exit(0);
        }
        if arg == "--version" || arg == "-V" {
            println!("{}", VERSION_STR);
            std::process::exit(0);
        }

        // Long option forms
        if arg.starts_with("--") {
            let (name, eq_val): (&str, Option<&str>) = match arg.find('=') {
                Some(i) => (&arg[2..i], Some(&arg[i+1..])),
                None => (&arg[2..], None),
            };
            let mut consume_val = |need_val: bool, pretty: &str| -> Result<Option<String>, ClapError> {
                if !need_val { return Ok(None); }
                if let Some(v) = eq_val { return Ok(Some(v.to_string())); }
                if idx + 1 >= argv.len() {
                    return Err(ClapError::new(format!(
                        "a value is required for '{}' but none was supplied", pretty)));
                }
                idx += 1;
                let v = argv[idx].clone();
                // clap allows values that begin with '-' if they are not options
                Ok(Some(v))
            };
            // Evaluate based on name
            let pretty = match name {
                "quality" => "--quality <QUALITY>",
                "lossless" => "--lossless",
                "max-size" => "--max-size <MAX_SIZE>",
                "width" => "--width <WIDTH>",
                "height" => "--height <HEIGHT>",
                "long-edge" => "--long-edge <LONG_EDGE>",
                "short-edge" => "--short-edge <SHORT_EDGE>",
                "no-upscale" => "--no-upscale",
                "output" => "--output <OUTPUT>",
                "same-folder-as-input" => "--same-folder-as-input",
                "format" => "--format <FORMAT>",
                "png-opt-level" => "--png-opt-level <PNG_OPT_LEVEL>",
                "jpeg-chroma-subsampling" => "--jpeg-chroma-subsampling <JPEG_CHROMA_SUBSAMPLING>",
                "jpeg-baseline" => "--jpeg-baseline",
                "zopfli" => "--zopfli",
                "exif" => "--exif",
                "keep-dates" => "--keep-dates",
                "strip-icc" => "--strip-icc",
                "suffix" => "--suffix <SUFFIX>",
                "recursive" => "--recursive",
                "keep-structure" => "--keep-structure",
                "dry-run" => "--dry-run",
                "threads" => "--threads <THREADS>",
                "overwrite" => "--overwrite <OVERWRITE>",
                "min-savings" => "--min-savings <MIN_SAVINGS>",
                "quiet" => "--quiet",
                "verbose" => "--verbose <VERBOSE>",
                _ => {
                    // Unknown long option
                    let tip = if let Some(best) = best_long_match(name) {
                        format!("a similar argument exists: '--{}'", best)
                    } else {
                        format!("to pass '{}' as a value, use '-- {}'", arg, arg)
                    };
                    let msg = format!("unexpected argument '{}' found\n\n  tip: {}", arg, tip);
                    return Err(ClapError::with_hint(msg, "".to_string()));
                }
            };

            match name {
                "quality" => {
                    let v = match eq_val { Some(v) => v.to_string(), None => {
                        if idx + 1 >= argv.len() {
                            return Err(ClapError::new(format!("a value is required for '{}' but none was supplied", pretty)));
                        }
                        idx += 1;
                        argv[idx].clone()
                    }};
                    let q: u32 = match v.parse::<u32>() {
                        Ok(x) => {
                            if x > 100 {
                                return Err(ClapError::new(format!(
                                    "invalid value '{}' for '{}': Quality must be between 0 and 100, but got {}",
                                    v, pretty, v)));
                            }
                            x
                        }
                        Err(_) => {
                            return Err(ClapError::new(format!(
                                "invalid value '{}' for '{}': '{}' is not a valid number",
                                v, pretty, v)));
                        }
                    };
                    check_compression_conflict("quality", &seen_order)?;
                    a.quality = Some(q);
                    mark("quality", &mut seen_order);
                }
                "lossless" => {
                    check_compression_conflict("lossless", &seen_order)?;
                    a.lossless = true;
                    mark("lossless", &mut seen_order);
                }
                "max-size" => {
                    let v = match eq_val { Some(v) => v.to_string(), None => {
                        if idx + 1 >= argv.len() {
                            return Err(ClapError::new(format!("a value is required for '{}' but none was supplied", pretty)));
                        }
                        idx += 1;
                        argv[idx].clone()
                    }};
                    let size = parse_byte_size(&v).map_err(|err| ClapError::new(format!(
                        "invalid value '{}' for '{}': Invalid size format: {}", v, pretty, err)))?;
                    check_compression_conflict("max-size", &seen_order)?;
                    a.max_size = Some(size);
                    mark("max-size", &mut seen_order);
                }
                "width" => {
                    let v = take_value(&mut idx, argv, eq_val, pretty)?;
                    let n = parse_u32_std(&v, pretty)?;
                    check_resize_conflict("width", &seen_order)?;
                    a.width = Some(n);
                    mark("width", &mut seen_order);
                }
                "height" => {
                    let v = take_value(&mut idx, argv, eq_val, pretty)?;
                    let n = parse_u32_std(&v, pretty)?;
                    check_resize_conflict("height", &seen_order)?;
                    a.height = Some(n);
                    mark("height", &mut seen_order);
                }
                "long-edge" => {
                    let v = take_value(&mut idx, argv, eq_val, pretty)?;
                    let n = parse_u32_std(&v, pretty)?;
                    check_resize_conflict("long-edge", &seen_order)?;
                    a.long_edge = Some(n);
                    mark("long-edge", &mut seen_order);
                }
                "short-edge" => {
                    let v = take_value(&mut idx, argv, eq_val, pretty)?;
                    let n = parse_u32_std(&v, pretty)?;
                    check_resize_conflict("short-edge", &seen_order)?;
                    a.short_edge = Some(n);
                    mark("short-edge", &mut seen_order);
                }
                "no-upscale" => { a.no_upscale = true; }
                "output" => {
                    let v = take_value(&mut idx, argv, eq_val, pretty)?;
                    check_output_conflict("output", &seen_order)?;
                    a.output = Some(v);
                    mark("output", &mut seen_order);
                }
                "same-folder-as-input" => {
                    check_output_conflict("same-folder-as-input", &seen_order)?;
                    a.same_folder_as_input = true;
                    mark("same-folder-as-input", &mut seen_order);
                }
                "format" => {
                    let v = take_value(&mut idx, argv, eq_val, pretty)?;
                    check_possible_values(&v, pretty, &["jpeg","png","gif","webp","tiff","original"])?;
                    a.format = v;
                }
                "png-opt-level" => {
                    let v = take_value(&mut idx, argv, eq_val, pretty)?;
                    let n: u32 = match v.parse::<u32>() {
                        Ok(x) => {
                            if x > 6 {
                                return Err(ClapError::new(format!(
                                    "invalid value '{}' for '{}': PNG optimization level must be between 0 and 6, but got {}",
                                    v, pretty, v)));
                            }
                            x
                        }
                        Err(_) => {
                            return Err(ClapError::new(format!(
                                "invalid value '{}' for '{}': '{}' is not a valid number",
                                v, pretty, v)));
                        }
                    };
                    a.png_opt_level = n;
                }
                "jpeg-chroma-subsampling" => {
                    let v = take_value(&mut idx, argv, eq_val, pretty)?;
                    check_possible_values(&v, pretty, &["4:4:4","4:2:2","4:2:0","4:1:1","auto"])?;
                    a.jpeg_chroma_subsampling = v;
                }
                "jpeg-baseline" => { a.jpeg_baseline = true; }
                "zopfli" => { a.zopfli = true; }
                "exif" => { a.exif = true; }
                "keep-dates" => { a.keep_dates = true; }
                "strip-icc" => { a.strip_icc = true; }
                "suffix" => {
                    let v = take_value(&mut idx, argv, eq_val, pretty)?;
                    a.suffix = Some(v);
                }
                "recursive" => { a.recursive = true; }
                "keep-structure" => { a.keep_structure = true; }
                "dry-run" => { a.dry_run = true; }
                "threads" => {
                    let v = take_value(&mut idx, argv, eq_val, pretty)?;
                    let n = parse_u32_std(&v, pretty)?;
                    a.threads = n;
                }
                "overwrite" => {
                    let v = take_value(&mut idx, argv, eq_val, pretty)?;
                    check_possible_values(&v, pretty, &["all","never","bigger"])?;
                    a.overwrite = v;
                }
                "min-savings" => {
                    let v = take_value(&mut idx, argv, eq_val, pretty)?;
                    let ms = parse_min_savings(&v).map_err(|_| ClapError::new(format!(
                        "invalid value '{}' for '{}': Invalid size format: '{}'. Use percentage (e.g., '10%'), size with unit (e.g., '100KB', '1MB'), or plain number as bytes",
                        v, pretty, v)))?;
                    a.min_savings = Some(ms);
                }
                "quiet" => {
                    if verbose_source.is_some() {
                        return Err(ClapError::with_hint(
                            "the argument '--verbose <VERBOSE>' cannot be used with '--quiet'".to_string(),
                            "--verbose <VERBOSE>".to_string()));
                    }
                    a.quiet = true;
                    quiet_source = Some("--quiet".to_string());
                }
                "verbose" => {
                    if quiet_source.is_some() {
                        let q = quiet_source.as_ref().unwrap();
                        return Err(ClapError::with_hint(
                            format!("the argument '{}' cannot be used with '--verbose <VERBOSE>'", q),
                            q.clone()));
                    }
                    let v = take_value(&mut idx, argv, eq_val, pretty)?;
                    let n: u32 = match v.parse::<u32>() {
                        Ok(x) => {
                            if x > 3 {
                                return Err(ClapError::new(format!(
                                    "invalid value '{}' for '{}': Verbosity must be between 0 and 3, but got {}",
                                    v, pretty, v)));
                            }
                            x
                        }
                        Err(_) => {
                            return Err(ClapError::new(format!(
                                "invalid value '{}' for '{}': invalid digit found in string",
                                v, pretty)));
                        }
                    };
                    a.verbose = n;
                    verbose_source = Some("--verbose".to_string());
                }
                _ => unreachable!(),
            }
            idx += 1;
            continue;
        }

        // Short options or negative-number
        if arg.starts_with('-') && arg.len() > 1 && !looks_like_negative_value(arg) {
            // Could be -q 80, -q=80, -qRS (combined), -q80
            let chars: Vec<char> = arg[1..].chars().collect();
            let mut ci = 0;
            while ci < chars.len() {
                let c = chars[ci];
                match c {
                    'h' => { print_short_help(); std::process::exit(0); }
                    'V' => { println!("{}", VERSION_STR); std::process::exit(0); }
                    'q' => {
                        // takes value: rest of chars if any, or = followed, or next arg
                        let val_str: String;
                        if ci + 1 < chars.len() {
                            let rest: String = chars[ci+1..].iter().collect();
                            val_str = if let Some(stripped) = rest.strip_prefix('=') { stripped.to_string() } else { rest };
                        } else {
                            if idx + 1 >= argv.len() {
                                return Err(ClapError::new("a value is required for '--quality <QUALITY>' but none was supplied".to_string()));
                            }
                            idx += 1;
                            val_str = argv[idx].clone();
                        }
                        let pretty = "--quality <QUALITY>";
                        let q: u32 = match val_str.parse::<u32>() {
                            Ok(x) => {
                                if x > 100 {
                                    return Err(ClapError::new(format!(
                                        "invalid value '{}' for '{}': Quality must be between 0 and 100, but got {}",
                                        val_str, pretty, val_str)));
                                }
                                x
                            }
                            Err(_) => {
                                return Err(ClapError::new(format!(
                                    "invalid value '{}' for '{}': '{}' is not a valid number",
                                    val_str, pretty, val_str)));
                            }
                        };
                        check_compression_conflict("quality", &seen_order)?;
                        a.quality = Some(q);
                        mark("quality", &mut seen_order);
                        break;
                    }
                    'o' => {
                        let val_str: String;
                        if ci + 1 < chars.len() {
                            let rest: String = chars[ci+1..].iter().collect();
                            val_str = if let Some(s) = rest.strip_prefix('=') { s.to_string() } else { rest };
                        } else {
                            if idx + 1 >= argv.len() {
                                return Err(ClapError::new("a value is required for '--output <OUTPUT>' but none was supplied".to_string()));
                            }
                            idx += 1;
                            val_str = argv[idx].clone();
                        }
                        check_output_conflict("output", &seen_order)?;
                        a.output = Some(val_str);
                        mark("output", &mut seen_order);
                        break;
                    }
                    'e' => { a.exif = true; ci += 1; continue; }
                    'R' => { a.recursive = true; ci += 1; continue; }
                    'S' => { a.keep_structure = true; ci += 1; continue; }
                    'd' => { a.dry_run = true; ci += 1; continue; }
                    'Q' => {
                        if verbose_source.is_some() {
                            return Err(ClapError::with_hint(
                                "the argument '--verbose <VERBOSE>' cannot be used with '--quiet'".to_string(),
                                "--verbose <VERBOSE>".to_string()));
                        }
                        a.quiet = true;
                        quiet_source = Some("--quiet".to_string());
                        ci += 1; continue;
                    }
                    'O' => {
                        let val_str: String;
                        if ci + 1 < chars.len() {
                            let rest: String = chars[ci+1..].iter().collect();
                            val_str = if let Some(s) = rest.strip_prefix('=') { s.to_string() } else { rest };
                        } else {
                            if idx + 1 >= argv.len() {
                                return Err(ClapError::new("a value is required for '--overwrite <OVERWRITE>' but none was supplied".to_string()));
                            }
                            idx += 1;
                            val_str = argv[idx].clone();
                        }
                        check_possible_values(&val_str, "--overwrite <OVERWRITE>", &["all","never","bigger"])?;
                        a.overwrite = val_str;
                        break;
                    }
                    _ => {
                        let tip = format!("to pass '-{}' as a value, use '-- -{}'", c, c);
                        let msg = format!("unexpected argument '-{}' found\n\n  tip: {}", c, tip);
                        return Err(ClapError::with_hint(msg, "".to_string()));
                    }
                }
            }
            idx += 1;
            continue;
        }

        // Negative number like "-1" or "-.." - unexpected argument
        if looks_like_negative_value(arg) {
            let tip = format!("to pass '{}' as a value, use '-- {}'", arg, arg);
            let msg = format!("unexpected argument '{}' found\n\n  tip: {}", arg, tip);
            return Err(ClapError::with_hint(msg, "".to_string()));
        }

        // Positional (file)
        a.files.push(arg.clone());
        idx += 1;
    }

    // Required arg group validation
    let has_compression = a.quality.is_some() || a.lossless || a.max_size.is_some();
    let has_output = a.output.is_some() || a.same_folder_as_input;
    if !has_compression && !has_output {
        let msg = "the following required arguments were not provided:\n  <--quality <QUALITY>|--lossless|--max-size <MAX_SIZE>>\n  <--output <OUTPUT>|--same-folder-as-input>".to_string();
        return Err(ClapError::with_hint(msg, "".to_string()));
    }
    if !has_compression {
        let msg = "the following required arguments were not provided:\n  <--quality <QUALITY>|--lossless|--max-size <MAX_SIZE>>".to_string();
        let hint = if !a.files.is_empty() { "with files".to_string() } else { "".to_string() };
        return Err(ClapError { msg, usage_hint: hint });
    }
    if !has_output {
        let msg = "the following required arguments were not provided:\n  <--output <OUTPUT>|--same-folder-as-input>".to_string();
        return Err(ClapError { msg, usage_hint: "".to_string() });
    }

    Ok(a)
}

fn take_value(idx: &mut usize, argv: &[String], eq_val: Option<&str>, pretty: &str) -> Result<String, ClapError> {
    if let Some(v) = eq_val { return Ok(v.to_string()); }
    if *idx + 1 >= argv.len() {
        return Err(ClapError::new(format!("a value is required for '{}' but none was supplied", pretty)));
    }
    *idx += 1;
    Ok(argv[*idx].clone())
}

fn parse_u32_std(v: &str, pretty: &str) -> Result<u32, ClapError> {
    match v.parse::<u32>() {
        Ok(x) => Ok(x),
        Err(e) => {
            let kind = format!("{}", e);
            let detail = if kind.contains("empty") {
                "cannot parse integer from empty string".to_string()
            } else if kind.contains("too large") || kind.contains("too small") || kind.contains("overflow") {
                "number too large to fit in target type".to_string()
            } else {
                "invalid digit found in string".to_string()
            };
            Err(ClapError::new(format!(
                "invalid value '{}' for '{}': {}",
                v, pretty, detail)))
        }
    }
}

fn check_possible_values(val: &str, pretty: &str, allowed: &[&str]) -> Result<(), ClapError> {
    if allowed.contains(&val) { return Ok(()); }
    let msg = format!(
        "invalid value '{}' for '{}'\n  [possible values: {}]",
        val, pretty, allowed.join(", "));
    Err(ClapError::with_hint(msg, "".to_string()))
}

fn check_compression_conflict(new: &str, order: &[&'static str]) -> Result<(), ClapError> {
    for &s in order {
        if s == "quality" || s == "lossless" || s == "max-size" {
            if s == new { continue; }
            let a = pretty_of(s);
            let b = pretty_of(new);
            return Err(ClapError::with_hint(
                format!("the argument '{}' cannot be used with '{}'", a, b),
                "".to_string(),
            ));
        }
    }
    Ok(())
}

fn check_output_conflict(new: &str, order: &[&'static str]) -> Result<(), ClapError> {
    for &s in order {
        if s == "output" || s == "same-folder-as-input" {
            if s == new { continue; }
            let a = pretty_of(s);
            let b = pretty_of(new);
            return Err(ClapError::with_hint(
                format!("the argument '{}' cannot be used with '{}'", a, b),
                "".to_string(),
            ));
        }
    }
    Ok(())
}

fn check_resize_conflict(new: &str, order: &[&'static str]) -> Result<(), ClapError> {
    // width/height are group 1 (both can coexist); long-edge and short-edge each alone
    // Rule: width or height cannot be used with long-edge/short-edge. long-edge cannot be used with short-edge.
    let is_wh = |s: &str| s == "width" || s == "height";
    let is_le = |s: &str| s == "long-edge";
    let is_se = |s: &str| s == "short-edge";
    for &s in order {
        let a = pretty_of(s);
        let b = pretty_of(new);
        if is_wh(s) && (is_le(new) || is_se(new)) { return Err(conflict(a,b)); }
        if is_le(s) && (is_wh(new) || is_se(new)) { return Err(conflict(a,b)); }
        if is_se(s) && (is_wh(new) || is_le(new)) { return Err(conflict(a,b)); }
    }
    Ok(())
}

fn conflict(a: String, b: String) -> ClapError {
    ClapError::with_hint(
        format!("the argument '{}' cannot be used with '{}'", a, b),
        a.clone(),
    )
}

fn pretty_of(name: &str) -> String {
    match name {
        "quality" => "--quality <QUALITY>".to_string(),
        "lossless" => "--lossless".to_string(),
        "max-size" => "--max-size <MAX_SIZE>".to_string(),
        "width" => "--width <WIDTH>".to_string(),
        "height" => "--height <HEIGHT>".to_string(),
        "long-edge" => "--long-edge <LONG_EDGE>".to_string(),
        "short-edge" => "--short-edge <SHORT_EDGE>".to_string(),
        "output" => "--output <OUTPUT>".to_string(),
        "same-folder-as-input" => "--same-folder-as-input".to_string(),
        "quiet" => "--quiet".to_string(),
        "verbose" => "--verbose <VERBOSE>".to_string(),
        _ => format!("--{}", name),
    }
}
