// ============================================================================
// Size parsing
// ============================================================================

// Parse a human size into bytes. Mimics behavior of the `bytesize` crate for
// --max-size: supports decimal prefixes (KB, MB, GB, TB, PB), binary prefixes
// (KiB, MiB, etc.), and a bare "B" suffix for bytes. Case-insensitive. No space
// between number and unit is allowed except optional space.
fn parse_byte_size(s: &str) -> Result<u64, String> {
    // Split numeric prefix from unit suffix. The numeric part is parsed as f64.
    let mut split = 0;
    let bytes = s.as_bytes();
    while split < bytes.len() {
        let c = bytes[split];
        if c.is_ascii_digit() || c == b'.' || c == b'+' || c == b'-' {
            split += 1;
        } else {
            break;
        }
    }
    let num_str = s[..split].trim();
    let unit_str = s[split..].trim();
    let num: f64 = match num_str.parse::<f64>() {
        Ok(n) => n,
        Err(_) => {
            return Err(format!(
                "couldn't parse \"{}\" into a ByteSize, cannot parse float from empty string",
                s));
        }
    };
    // Overflow test for gigantic pre-unit numbers
    if !num.is_finite() {
        return Err(format!(
            "couldn't parse \"\" into a known SI unit, Failed to parse unit \"\""));
    }
    let mult: u64 = match unit_str.to_lowercase().as_str() {
        "" | "b" => 1,
        "k" | "kb" => 1_000,
        "kib" => 1_024,
        "m" | "mb" => 1_000_000,
        "mib" => 1_048_576,
        "g" | "gb" => 1_000_000_000,
        "gib" => 1_073_741_824,
        "t" | "tb" => 1_000_000_000_000,
        "tib" => 1_099_511_627_776,
        "p" | "pb" => 1_000_000_000_000_000,
        "pib" => 1_125_899_906_842_624,
        other => {
            return Err(format!(
                "couldn't parse \"{}\" into a known SI unit, Failed to parse unit \"{}\"",
                other, other));
        }
    };
    let bytes = (num * mult as f64).round();
    if bytes < 0.0 { return Err("negative size".to_string()); }
    Ok(bytes as u64)
}

fn parse_min_savings(s: &str) -> Result<MinSavings, String> {
    let t = s.trim();
    if t.ends_with('%') {
        let body = &t[..t.len()-1];
        let v: f64 = body.parse().map_err(|_| format!("bad percent '{}'", s))?;
        return Ok(MinSavings::Percent(v));
    }
    if t.is_empty() { return Err("empty".to_string()); }
    // Try plain number: interpret as bytes
    if let Ok(n) = t.parse::<u64>() {
        return Ok(MinSavings::Bytes(n));
    }
