// ============================================================================
// Image format detection via magic bytes
// ============================================================================

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ImageFormat {
    Jpeg, Png, WebP, Gif,
}

fn detect_format(bytes: &[u8]) -> Option<ImageFormat> {
    if bytes.len() >= 3 && bytes[0] == 0xFF && bytes[1] == 0xD8 && bytes[2] == 0xFF {
        return Some(ImageFormat::Jpeg);
    }
    if bytes.len() >= 8 && &bytes[0..8] == b"\x89PNG\r\n\x1a\n" {
        return Some(ImageFormat::Png);
    }
    if bytes.len() >= 12 && &bytes[0..4] == b"RIFF" && &bytes[8..12] == b"WEBP" {
        return Some(ImageFormat::WebP);
    }
    if bytes.len() >= 6 && (&bytes[0..6] == b"GIF87a" || &bytes[0..6] == b"GIF89a") {
        return Some(ImageFormat::Gif);
    }
    None
}

fn sniff_file(path: &Path) -> Option<ImageFormat> {
    let mut f = match fs::File::open(path) {
        Ok(f) => f,
        Err(_) => return None,
    };
    let mut buf = [0u8; 16];
    let n = match f.read(&mut buf) {
        Ok(n) => n,
        Err(_) => return None,
    };
    detect_format(&buf[..n])
}

// ============================================================================
// File discovery
// ============================================================================

// Walk a directory; collect image files (using magic byte detection).
fn walk_dir(dir: &Path, recursive: bool, out: &mut Vec<PathBuf>) {
    let entries = match fs::read_dir(dir) {
        Ok(e) => e,
        Err(_) => return,
    };
    let mut subdirs = Vec::new();
    let mut files = Vec::new();
    for e in entries.flatten() {
        let p = e.path();
        let ft = match e.file_type() {
            Ok(ft) => ft,
            Err(_) => continue,
        };
        if ft.is_dir() {
            subdirs.push(p);
        } else if ft.is_file() {
            files.push(p);
        }
    }
    // Sort files so output is deterministic. Names first, then subdirs.
    files.sort();
    subdirs.sort();
    for f in files {
        if sniff_file(&f).is_some() {
            out.push(f);
        }
    }
    if recursive {
        for d in subdirs {
            walk_dir(&d, recursive, out);
        }
    }
}

// Expand an input path into image files. For single file, check magic.
fn expand_input(p: &Path, recursive: bool, out: &mut Vec<PathBuf>) {
    if p.is_dir() {
        walk_dir(p, recursive, out);
    } else if p.is_file() {
        if sniff_file(p).is_some() {
            out.push(p.to_path_buf());
        }
    }
    // Non-existent: silently skip.
}

// Compute the common parent directory for a set of paths. Mirrors the "base
// path" logic used when --keep-structure is enabled with multiple/recursed inputs.
fn common_parent(paths: &[PathBuf]) -> Option<PathBuf> {
    if paths.is_empty() { return None; }
    // If only one path: its parent directory
    if paths.len() == 1 {
        return paths[0].parent().map(|p| p.to_path_buf());
    }
    let first = paths[0].parent().unwrap_or(Path::new(""));
    let first_components: Vec<Component> = first.components().collect();
    let mut common_len = first_components.len();
    for p in &paths[1..] {
        let par = p.parent().unwrap_or(Path::new(""));
        let comps: Vec<Component> = par.components().collect();
        let mut i = 0;
        while i < common_len && i < comps.len() && first_components[i] == comps[i] {
            i += 1;
        }
        common_len = i;
        if common_len == 0 { break; }
    }
    let mut result = PathBuf::new();
    for c in &first_components[..common_len] {
        result.push(c);
    }
    Some(result)
}

// ============================================================================
// Output path computation
// ============================================================================

fn compute_output_path(args: &Args, base_root: &Path, input: &Path) -> Option<PathBuf> {
    let filename = input.file_name()?;
    // Determine output directory
    let (out_dir, use_keep_structure) = if args.same_folder_as_input {
        (input.parent().unwrap_or(Path::new("")).to_path_buf(), false)
    } else {
        let od = PathBuf::from(args.output.as_ref().unwrap());
        (od, args.keep_structure)
    };

    // Compute final path
    let stem_ext = {
        let stem = Path::new(filename).file_stem()?.to_string_lossy().to_string();
        let ext = match Path::new(filename).extension() {
            Some(e) => e.to_string_lossy().to_string(),
            None => String::new(),
        };
        (stem, ext)
    };
    let (stem, mut ext) = stem_ext;
    // Apply suffix and format override
    if args.format != "original" {
        ext = match args.format.as_str() {
            "jpeg" => "jpg".to_string(),
            "png" => "png".to_string(),
            "webp" => "webp".to_string(),
            "gif" => "gif".to_string(),
            "tiff" => "tiff".to_string(),
            _ => ext,
        };
    }
    let suffix = args.suffix.as_deref().unwrap_or("");
    let new_name = if ext.is_empty() {
        format!("{}{}", stem, suffix)
    } else {
        format!("{}{}.{}", stem, suffix, ext)
    };

    let mut p = out_dir.clone();
    if use_keep_structure {
        // Compute relative from base_root
        if let Ok(rel) = input.strip_prefix(base_root) {
            let parent = rel.parent().unwrap_or(Path::new(""));
            p = p.join(parent);
        }
    }
    p.push(new_name);
    Some(p)
}

// ============================================================================
// Main processing
// ============================================================================

struct Outcome {
    status: Status,
    orig: u64,
    new: u64,
    reason: Option<String>,
}

enum Status { Success, Skipped, Error }

fn process_file(args: &Args, input: &Path, output: &Path) -> Outcome {
    let orig = match fs::metadata(input) {
        Ok(m) => m.len(),
        Err(_) => return Outcome { status: Status::Error, orig: 0, new: 0, reason: Some("cannot read".into()) },
    };

    if args.dry_run {
        return Outcome { status: Status::Success, orig, new: orig, reason: None };
    }

    // If overwrite policy blocks, skip without writing.
    if output.exists() {
        match args.overwrite.as_str() {
            "never" => {
                return Outcome { status: Status::Skipped, orig, new: orig, reason: Some("File already exists, skipped due overwrite policy".into()) };
            }
            "bigger" => {
                let existing_len = fs::metadata(output).map(|m| m.len()).unwrap_or(0);
                // We don't actually compress; use orig as simulated new size.
                let new_size = orig;
                if existing_len <= new_size {
                    return Outcome { status: Status::Skipped, orig, new: orig, reason: Some("File already exists, skipped due overwrite policy".into()) };
                }
            }
            _ => {}
        }
    }

    // "Compress" by copying; treat the output size as the same as the input.
    if let Some(parent) = output.parent() {
        let _ = fs::create_dir_all(parent);
    }
    let new_size = orig;
    match fs::copy(input, output) {
        Ok(_) => {}
        Err(e) => return Outcome { status: Status::Error, orig, new: 0, reason: Some(format!("{}", e)) },
    }

    // min-savings check. With our pretend-compression, the "new" size is always orig.
    if let Some(ms) = &args.min_savings {
        let pct_saved_abs = if orig == 0 { 0.0 } else { (orig as f64 - new_size as f64) / orig as f64 * 100.0 };
        match ms {
