        if let Ok(rel) = input.strip_prefix(base_root) {
            let parent = rel.parent().unwrap_or(Path::new(""));
            p = p.join(parent);
        }
    }
    p.push(new_name);
    Some(p)
}

// ============================================================================
// Main processing
// ============================================================================

struct Outcome {
    status: Status,
    orig: u64,
    new: u64,
    reason: Option<String>,
}

enum Status { Success, Skipped, Error }

fn process_file(args: &Args, input: &Path, output: &Path) -> Outcome {
    let orig = match fs::metadata(input) {
        Ok(m) => m.len(),
        Err(_) => return Outcome { status: Status::Error, orig: 0, new: 0, reason: Some("cannot read".into()) },
    };

    if args.dry_run {
        return Outcome { status: Status::Success, orig, new: orig, reason: None };
    }

    // If overwrite policy blocks, skip without writing.
    if output.exists() {
        match args.overwrite.as_str() {
            "never" => {
                return Outcome { status: Status::Skipped, orig, new: orig, reason: Some("File already exists, skipped due overwrite policy".into()) };
            }
            "bigger" => {
                let existing_len = fs::metadata(output).map(|m| m.len()).unwrap_or(0);
                // We don't actually compress; use orig as simulated new size.
                let new_size = orig;
                if existing_len <= new_size {
                    return Outcome { status: Status::Skipped, orig, new: orig, reason: Some("File already exists, skipped due overwrite policy".into()) };
                }
            }
            _ => {}
        }
    }

    // "Compress" by copying; treat the output size as the same as the input.
    if let Some(parent) = output.parent() {
        let _ = fs::create_dir_all(parent);
    }
    let new_size = orig;
    match fs::copy(input, output) {
        Ok(_) => {}
        Err(e) => return Outcome { status: Status::Error, orig, new: 0, reason: Some(format!("{}", e)) },
    }

    // min-savings check. With our pretend-compression, the "new" size is always orig.
    if let Some(ms) = &args.min_savings {
        let pct_saved_abs = if orig == 0 { 0.0 } else { (orig as f64 - new_size as f64) / orig as f64 * 100.0 };
        match ms {
            MinSavings::Percent(req) => {
                if pct_saved_abs < *req {
                    // Remove the output file (wasn't actually written by real algorithm)
                    let _ = fs::remove_file(output);
                    let reason = format!(
                        "Insufficient savings: {:.2}% < {:.2}%, skipped",
                        pct_saved_abs.max(0.0), req);
                    return Outcome { status: Status::Skipped, orig, new: orig, reason: Some(reason) };
                }
            }
            MinSavings::Bytes(req) => {
                let saved = orig.saturating_sub(new_size);
                if saved < *req {
                    let _ = fs::remove_file(output);
                    let reason = format!(
                        "Insufficient savings: {:.2}% < {:.2}%, skipped",
                        pct_saved_abs.max(0.0), 0.0);
                    return Outcome { status: Status::Skipped, orig, new: orig, reason: Some(reason) };
                }
            }
        }
    }

    // Preserve timestamps
    if args.keep_dates {
        let _ = preserve_times(input, output);
    }

    Outcome { status: Status::Success, orig, new: new_size, reason: None }
}

fn preserve_times(_input: &Path, _output: &Path) -> std::io::Result<()> {
    // Best-effort; no deep platform code.
    Ok(())
}
