fn main() -> ExitCode {
    let argv: Vec<String> = env::args().collect();
    let args = match parse_args(&argv) {
        Ok(a) => a,
        Err(e) => return emit_clap_error(&e, false),
    };

    // Determine effective verbose level
    let verbose = if args.quiet { 0 } else { args.verbose };

    // Expand inputs
    let mut files: Vec<PathBuf> = Vec::new();
    for input in &args.files {
        expand_input(Path::new(input), args.recursive, &mut files);
    }
    // Deterministic order (directory walk already sorts)
    // ... but preserving original order of CLI inputs with within-dir ordering
    // Drop duplicates
    {
        let mut seen = BTreeSet::new();
        files.retain(|f| seen.insert(f.clone()));
    }
    if files.is_empty() {
        if args.files.is_empty() {
            if verbose >= 1 { println!("No files to compress"); }
            return ExitCode::from(0);
        } else {
            // "Unable to compute the base path for the files."
            if verbose >= 1 { println!("Unable to compute the base path for the files."); }
            return ExitCode::from(255);
        }
    }

    // Compute base path (for --keep-structure)
    let base_root = common_parent(&files).unwrap_or_else(|| PathBuf::from(""));

    // Process each file
    let mut total_orig: u64 = 0;
    let mut total_new: u64 = 0;
    let mut successes: u64 = 0;
    let mut skipped: u64 = 0;
    let mut errors: u64 = 0;
    let mut msgs: Vec<String> = Vec::new();

    for input in &files {
        let output = match compute_output_path(&args, &base_root, input) {
            Some(p) => p,
            None => {
                errors += 1;
                continue;
            }
        };
        let outc = process_file(&args, input, &output);
        match outc.status {
            Status::Success => {
                total_orig += outc.orig;
                total_new += outc.new;
                successes += 1;
                if verbose >= 3 {
                    let mut line = String::new();
                    line.push_str(&format!("[Success] {} -> {}\n",
                        input.display(), output.display()));
                    let delta = outc.new as i64 - outc.orig as i64;
                    line.push_str(&format!("{} -> {} [{} | {}]\n",
                        format_size(outc.orig), format_size(outc.new),
                        format_size_signed(delta), percent_str(outc.orig, outc.new)));
                    msgs.push(line);
                }
            }
            Status::Skipped => {
                total_orig += outc.orig;
                total_new += outc.orig;
                skipped += 1;
                if verbose >= 2 {
                    let mut line = String::new();
                    line.push_str(&format!("[Skipped] {} -> {}\n",
                        input.display(), output.display()));
                    let delta = outc.new as i64 - outc.orig as i64;
                    line.push_str(&format!("{} -> {} [{} | {}]\n",
                        format_size(outc.orig), format_size(outc.new),
                        format_size_signed(delta), percent_str(outc.orig, outc.new)));
                    if let Some(r) = outc.reason {
                        line.push_str(&format!("{}\n", r));
                    }
                    msgs.push(line);
                }
            }
            Status::Error => {
                errors += 1;
                if verbose >= 2 {
                    let mut line = String::new();
                    line.push_str(&format!("[Error] {}\n", input.display()));
                    if let Some(r) = outc.reason {
                        line.push_str(&format!("{}\n", r));
                    }
                    msgs.push(line);
                }
            }
        }
    }

    // Print per-file messages with blank line between
    if verbose >= 2 {
        for m in &msgs {
            println!("{}", m);
        }
    }

    // Summary line
    if verbose >= 1 {
        let total_count = successes + skipped + errors;
        println!("Compressed {} files ({} success, {} skipped, {} errors)",
            total_count, successes, skipped, errors);
        let delta = total_new as i64 - total_orig as i64;
        println!("{} -> {} [{} | {}]",
            format_size(total_orig), format_size(total_new),
            format_size_signed(delta), percent_str(total_orig, total_new));
    }

    ExitCode::from(0)
}
