# Fix emit_clap_error logic and parse-time tracking.
# I'll do this with sed/awk since it's a targeted refactor.
import re
p = open('src/main.rs').read()
# Add new field to ClapError: usage_mode
p = p.replace('''struct ClapError {
    msg: String,
    usage_hint: String, // parts between "Usage: executable " and " <--quality..."
}''',
'''#[derive(Clone, Copy, PartialEq, Eq)]
enum UsageMode { OptionsPrefix, NoPrefix, NoUsage }

struct ClapError {
    msg: String,
    usage_hint: String, // e.g. "--width <WIDTH>" or "--quiet" to prepend before <--quality...>
    usage_mode: UsageMode,
    files_provided: bool,
}''')
p = p.replace('''impl ClapError {
    fn new(msg: String) -> Self {
        ClapError { msg, usage_hint: String::new() }
    }
    fn with_hint(msg: String, hint: String) -> Self {
        ClapError { msg, usage_hint: hint }
    }
}''',
'''impl ClapError {
    fn new(msg: String) -> Self {
        ClapError { msg, usage_hint: String::new(), usage_mode: UsageMode::OptionsPrefix, files_provided: false }
    }
    fn with_hint(msg: String, hint: String) -> Self {
        ClapError { msg, usage_hint: hint, usage_mode: UsageMode::OptionsPrefix, files_provided: false }
    }
    fn no_prefix(mut self) -> Self { self.usage_mode = UsageMode::NoPrefix; self }
    fn no_usage(mut self) -> Self { self.usage_mode = UsageMode::NoUsage; self }
    fn files_provided(mut self, b: bool) -> Self { self.files_provided = b; self }
}''')
# Replace emit_clap_error body
p = p.replace('''fn emit_clap_error(e: &ClapError, req_files: bool) -> ExitCode {
    let _ = writeln!(std::io::stderr(), "error: {}", e.msg);
    let _ = writeln!(std::io::stderr());
    if !req_files {
        let _ = writeln!(std::io::stderr(), "{}", usage_line_default());
    } else {
        let files_part = if req_files { "<FILES>..." } else { "[FILES]..." };
        let prefix = if e.usage_hint.is_empty() {
            String::new()
        } else {
            format!("{} ", e.usage_hint)
        };
        let _ = writeln!(std::io::stderr(),
            "Usage: executable {}<--quality <QUALITY>|--lossless|--max-size <MAX_SIZE>> <--output <OUTPUT>|--same-folder-as-input> {}",
            prefix, files_part);
    }
    let _ = writeln!(std::io::stderr());
    let _ = writeln!(std::io::stderr(), "For more information, try '--help'.");
    ExitCode::from(2)
}''',
'''fn emit_clap_error(e: &ClapError) -> ExitCode {
    let _ = writeln!(std::io::stderr(), "error: {}", e.msg);
    if e.usage_mode != UsageMode::NoUsage {
        let _ = writeln!(std::io::stderr());
        let prefix = match e.usage_mode {
            UsageMode::OptionsPrefix => "[OPTIONS] ".to_string(),
            UsageMode::NoPrefix => {
                if e.usage_hint.is_empty() { String::new() } else { format!("{} ", e.usage_hint) }
            }
            UsageMode::NoUsage => unreachable!(),
        };
        let files_part = if e.files_provided { "<FILES>..." } else { "[FILES]..." };
        let _ = writeln!(std::io::stderr(),
            "Usage: executable {}<--quality <QUALITY>|--lossless|--max-size <MAX_SIZE>> <--output <OUTPUT>|--same-folder-as-input> {}",
            prefix, files_part);
    }
    let _ = writeln!(std::io::stderr());
    let _ = writeln!(std::io::stderr(), "For more information, try '--help'.");
    ExitCode::from(2)
}''')
open('src/main.rs','w').write(p)
print('done')
