# Fix all callsites to use new ClapError API
import re
p = open('src/main.rs').read()

# Fix emit_clap_error call in main
p = p.replace('return emit_clap_error(&e, false),', 'return emit_clap_error(&e),')

# Fix the two struct literal construct sites (lines 726, 730)
p = p.replace('''        return Err(ClapError { msg, usage_hint: hint });''',
'''        return Err(ClapError { msg, usage_hint: hint, usage_mode: UsageMode::NoPrefix, files_provided: !a.files.is_empty() });''')
p = p.replace('''        return Err(ClapError { msg, usage_hint: "".to_string() });''',
'''        return Err(ClapError { msg, usage_hint: "".to_string(), usage_mode: UsageMode::NoPrefix, files_provided: !a.files.is_empty() });''')

# Fix possible_values error: no usage line
p = p.replace('''fn check_possible_values(val: &str, pretty: &str, allowed: &[&str]) -> Result<(), ClapError> {
    if allowed.contains(&val) { return Ok(()); }
    let msg = format!(
        "invalid value '{}' for '{}'\\n  [possible values: {}]",
        val, pretty, allowed.join(", "));
    Err(ClapError::with_hint(msg, "".to_string()))
}''',
'''fn check_possible_values(val: &str, pretty: &str, allowed: &[&str]) -> Result<(), ClapError> {
    if allowed.contains(&val) { return Ok(()); }
    let msg = format!(
        "invalid value '{}' for '{}'\\n  [possible values: {}]",
        val, pretty, allowed.join(", "));
    Err(ClapError::with_hint(msg, "".to_string()).no_usage())
}''')

# Conflict errors should use NoPrefix and files_provided flag set when files have been seen.
# Need to pass files_seen info from parse_args. Let's instead make a helper that
# reads files_provided later. We add a separate field set via chain.
# For conflict(), we need an externally tracked files_provided. Instead, let check_conflict
# functions return an error with NoPrefix and let parse_args set files_provided later in main.
#
# Let me add a post-process step at emit time: if error is NoPrefix and hint is empty,
# it's a conflict within req groups (remove [OPTIONS]); if hint is set, it's a different conflict.

# Set NoPrefix on all "conflict" errors. Modify conflict() to call .no_prefix()
p = p.replace('''fn conflict(a: String, b: String) -> ClapError {
    ClapError::with_hint(
        format!("the argument '{}' cannot be used with '{}'", a, b),
        a.clone(),
    )
}''',
'''fn conflict(a: String, b: String) -> ClapError {
    ClapError::with_hint(
        format!("the argument '{}' cannot be used with '{}'", a, b),
        a.clone(),
    ).no_prefix()
}''')

# For check_compression_conflict and check_output_conflict and check_resize_conflict, change behavior:
# - comp/output conflicts: no hint (no prefix arg), NoPrefix
# - resize conflicts: hint is the first conflicting arg, NoPrefix

# Update check_compression_conflict
p = p.replace('''fn check_compression_conflict(new: &str, order: &[&'static str]) -> Result<(), ClapError> {
    for &s in order {
        if s == "quality" || s == "lossless" || s == "max-size" {
            if s == new { continue; }
            let a = pretty_of(s);
            let b = pretty_of(new);
            return Err(ClapError::with_hint(
                format!("the argument '{}' cannot be used with '{}'", a, b),
                "".to_string(),
            ));
        }
    }
    Ok(())
}''',
'''fn check_compression_conflict(new: &str, order: &[&'static str]) -> Result<(), ClapError> {
    for &s in order {
        if s == "quality" || s == "lossless" || s == "max-size" {
            if s == new { continue; }
            let a = pretty_of(s);
            let b = pretty_of(new);
            return Err(ClapError::with_hint(
                format!("the argument '{}' cannot be used with '{}'", a, b),
                "".to_string(),
            ).no_prefix());
        }
    }
    Ok(())
}''')

p = p.replace('''fn check_output_conflict(new: &str, order: &[&'static str]) -> Result<(), ClapError> {
    for &s in order {
        if s == "output" || s == "same-folder-as-input" {
            if s == new { continue; }
            let a = pretty_of(s);
            let b = pretty_of(new);
            return Err(ClapError::with_hint(
                format!("the argument '{}' cannot be used with '{}'", a, b),
                "".to_string(),
            ));
        }
    }
    Ok(())
}''',
'''fn check_output_conflict(new: &str, order: &[&'static str]) -> Result<(), ClapError> {
    for &s in order {
        if s == "output" || s == "same-folder-as-input" {
            if s == new { continue; }
            let a = pretty_of(s);
            let b = pretty_of(new);
            return Err(ClapError::with_hint(
                format!("the argument '{}' cannot be used with '{}'", a, b),
                "".to_string(),
            ).no_prefix());
        }
    }
    Ok(())
}''')

